=== FILE: irq_ctrl_cov_tb.sv ===
// Coverage testbench for irq_ctrl.v: self-checking, N = 32 so that every
// register bit reaches a port (at N = 8, rdata[30:8] and irq_id[4:3] are tied
// to zero by construction). Inputs change 1 ns after a rising edge.
`timescale 1ns / 1ps
module irq_ctrl_cov_tb;
    localparam int N = 32;
    logic         clk = 1'b0;
    logic         rst_n = 1'b0;
    logic [N-1:0] src = '0;
    logic         we = 1'b0;
    logic [1:0]   addr = 2'd0;
    logic [31:0]  wdata = 32'd0;
    logic [31:0]  rdata;
    logic         irq;
    logic [4:0]   irq_id;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    irq_ctrl #(.N(N)) dut (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
                           .rdata(rdata), .irq(irq), .irq_id(irq_id));
    always #5 clk = ~clk;

    task automatic tick();
        @(posedge clk);
        #1;
    endtask

    task automatic write_reg(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1;
        addr = a;
        wdata = d;
        tick();
        we = 1'b0;
        wdata = 32'd0;
    endtask

    task automatic expect_reg(input logic [1:0] a, input logic [31:0] expected);
        addr = a;
        #1;
        checks++;
        if (rdata !== expected) begin
            errors++;
            $display("MISMATCH at %0t: addr %0d rdata %h expected %h", $time, a, rdata, expected);
        end
    endtask

    task automatic expect_irq(input logic e_irq, input logic [4:0] e_id);
        #1;
        checks++;
        if (irq !== e_irq || irq_id !== e_id) begin
            errors++;
            $display("MISMATCH at %0t: irq %b irq_id %0d expected %b %0d", $time, irq, irq_id, e_irq, e_id);
        end
    endtask

    initial begin
        // 1. Reset and reset values.
        repeat (3) @(posedge clk);
        #1;
        rst_n = 1'b1;
        tick();
        expect_reg(2'd0, 32'd0);
        expect_reg(2'd1, 32'd0);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0, 5'd0);

        // 2. Register read/write, full width.
        write_reg(2'd0, 32'hFFFF_FFFF);
        expect_reg(2'd0, 32'hFFFF_FFFF);
        write_reg(2'd0, 32'h0000_0000);
        expect_reg(2'd0, 32'h0000_0000);
        write_reg(2'd0, 32'hA5A5_A5A5);
        expect_reg(2'd0, 32'hA5A5_A5A5);
        write_reg(2'd0, 32'h5A5A_5A5A);
        expect_reg(2'd0, 32'h5A5A_5A5A);
        write_reg(2'd0, 32'h0000_0000);
        expect_reg(2'd0, 32'h0000_0000);
        write_reg(2'd1, 32'hFFFF_FFFF);
        expect_reg(2'd1, 32'hFFFF_FFFF);
        write_reg(2'd1, 32'h0000_0000);
        expect_reg(2'd1, 32'h0000_0000);
        write_reg(2'd2, 32'hFFFF_FFFF);      // W1C with nothing pending
        expect_reg(2'd2, 32'd0);
        write_reg(2'd3, 32'd31);             // acknowledge with nothing pending
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);

        // 3. Level detection on every source, masked by enable, then a claim sweep.
        src = '1;
        tick();
        expect_reg(2'd2, 32'hFFFF_FFFF);
        expect_irq(1'b0, 5'd0);              // nothing enabled
        src = '0;
        tick();
        expect_reg(2'd2, 32'hFFFF_FFFF);     // pending holds after the source drops
        write_reg(2'd0, 32'hFFFF_FFFF);
        expect_irq(1'b1, 5'd0);
        for (int k = 0; k < N; k++) begin
            expect_irq(1'b1, 5'(k));
            expect_reg(2'd3, 32'h8000_0000 | 32'(k));
            write_reg(2'd3, 32'(k));
        end
        expect_irq(1'b0, 5'd0);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);

        // 4. Edge mode: a rising edge sets pending, a held source does not re-trigger.
        write_reg(2'd1, 32'hFFFF_FFFF);
        expect_reg(2'd1, 32'hFFFF_FFFF);
        src = '1;
        tick();
        expect_reg(2'd2, 32'hFFFF_FFFF);
        expect_irq(1'b1, 5'd0);
        tick();
        expect_reg(2'd2, 32'hFFFF_FFFF);
        write_reg(2'd2, 32'hFFFF_FFFF);      // clear while the sources stay high
        expect_reg(2'd2, 32'd0);
        expect_irq(1'b0, 5'd0);
        src = '0;
        tick();                              // falling edge: no detection
        expect_reg(2'd2, 32'd0);

        // Edge detection wins over a clear at the same edge.
        src = 32'h0000_0020;
        write_reg(2'd2, 32'h0000_0020);
        expect_reg(2'd2, 32'h0000_0020);
        expect_irq(1'b1, 5'd5);
        write_reg(2'd2, 32'h0000_0020);      // source still high, no new edge
        expect_reg(2'd2, 32'd0);
        src = '0;
        tick();

        // Level detection wins over a clear while the source is high.
        write_reg(2'd1, 32'd0);
        src = 32'h0000_0008;
        tick();
        expect_reg(2'd2, 32'h0000_0008);
        expect_irq(1'b1, 5'd3);
        write_reg(2'd2, 32'h0000_0008);
        expect_reg(2'd2, 32'h0000_0008);
        src = '0;
        write_reg(2'd2, 32'h0000_0008);
        expect_reg(2'd2, 32'd0);
        expect_irq(1'b0, 5'd0);

        // 5. Masking and priority among a subset.
        src = 32'h0000_0F00;
        tick();
        src = '0;
        tick();
        expect_reg(2'd2, 32'h0000_0F00);
        expect_irq(1'b1, 5'd8);
        write_reg(2'd0, 32'h0000_0C00);
        expect_irq(1'b1, 5'd10);
        expect_reg(2'd3, 32'h8000_000A);
        write_reg(2'd0, 32'd0);
        expect_irq(1'b0, 5'd0);
        expect_reg(2'd3, 32'd0);
        expect_reg(2'd2, 32'h0000_0F00);
        write_reg(2'd0, 32'h0000_0F00);
        expect_irq(1'b1, 5'd8);
        write_reg(2'd3, 32'hFFFF_FFE9);      // only wdata[4:0] = 9 counts
        expect_reg(2'd2, 32'h0000_0D00);
        expect_irq(1'b1, 5'd8);
        write_reg(2'd3, 32'd0);              // acknowledge of a source not pending
        expect_reg(2'd2, 32'h0000_0D00);
        write_reg(2'd3, 32'd8);
        expect_reg(2'd2, 32'h0000_0C00);
        expect_irq(1'b1, 5'd10);

        // 6. Reset in mid-test, with sources held high.
        write_reg(2'd1, 32'h1234_5678);
        expect_reg(2'd1, 32'h1234_5678);
        rst_n = 1'b0;
        src = '1;
        tick();
        tick();
        expect_reg(2'd0, 32'd0);
        expect_reg(2'd1, 32'd0);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0, 5'd0);
        src = '0;
        tick();
        rst_n = 1'b1;
        tick();
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd0, 32'd0);
        expect_irq(1'b0, 5'd0);

        // The highest source after reset.
        src = 32'h8000_0000;
        tick();
        write_reg(2'd0, 32'h8000_0000);
        expect_irq(1'b1, 5'd31);
        expect_reg(2'd3, 32'h8000_001F);
        src = '0;
        write_reg(2'd3, 32'd31);
        expect_irq(1'b0, 5'd0);
        expect_reg(2'd2, 32'd0);

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
